@main
struct MyApp: App {
    @Environment(\.scenePhase) var scenePhase

    var body: some Scene {
        WindowGroup {
            ContentView()
        }
        .onChange(of: scenePhase) { oldPhase, newPhase in
            switch newPhase {
            case .active:
                print("App is active — refresh data")
            case .inactive:
                print("App is inactive — pause timers")
            case .background:
                print("App in background — save state")
                saveAppState()
            @unknown default:
                break
            }
        }
    }
}

// Register in App init or didFinishLaunching
BGTaskScheduler.shared.register(
    forTaskWithIdentifier: "com.app.refresh",
    using: nil
) { task in
    handleAppRefresh(task: task as! BGAppRefreshTask)
}

// Schedule when going to background
func scheduleRefresh() {
    let request = BGAppRefreshTaskRequest(
        identifier: "com.app.refresh"
    )
    request.earliestBeginDate = Date(timeIntervalSinceNow: 3600)
    try? BGTaskScheduler.shared.submit(request)
}

func handleAppRefresh(task: BGAppRefreshTask) {
    scheduleRefresh()  // reschedule for next time

    let syncTask = Task {
        await syncLatestData()
        task.setTaskCompleted(success: true)
    }

    task.expirationHandler = {
        syncTask.cancel()
    }
}

enum DeepLink {
    case profile(id: Int)
    case settings
    case unknown

    init(url: URL) {
        let components = URLComponents(url: url, resolvingAgainstBaseURL: false)
        let path = components?.path ?? ""

        if path.starts(with: "/profile/"),
           let id = Int(path.replacingOccurrences(of: "/profile/", with: "")) {
            self = .profile(id: id)
        } else if path == "/settings" {
            self = .settings
        } else {
            self = .unknown
        }
    }
}

@main
struct MyApp: App {
    @State private var selectedTab = 0

    var body: some Scene {
        WindowGroup {
            TabView(selection: $selectedTab) { /* ... */ }
                .onOpenURL { url in
                    let link = DeepLink(url: url)
                    switch link {
                    case .profile(let id):
                        selectedTab = 1
                        navigateToProfile(id)
                    case .settings:
                        selectedTab = 2
                    case .unknown:
                        break
                    }
                }
        }
    }
}
